// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url:             pw('paperless_url'),
    paperless_url_oeffentlich: pw('paperless_url_oeffentlich'),
    empfaenger_email:          pw('mail_betrieb'),
    absender:                  pw('mail_absender'),

    // ── fachlich, hier zu pflegen ──
    // vorlauf_tage: wie viele Tage im Voraus gewarnt wird.
    // Die Feldnamen müssen zu den Custom Fields passen, die
    // vertragsdaten-erkennen-mistral befüllt.
    vorlauf_tage: 90,
    feld_kuendigen_bis: 'Kündigen bis',
    feld_vertragsende: 'Vertragsende',
    feld_frist: 'Kündigungsfrist'
  }
}];

// Feld-IDs auflösen und die Abfrage vorbereiten.
// "Kündigen bis" ist Pflicht (Abfragefeld); Vertragsende/Kündigungsfrist
// sind nur Anzeige und dürfen fehlen (dann steht '-' in der Mail).
const cfg = $('Konfiguration').first().json;
const fields = $json.results || [];
const find = (name) => fields.find(f => String(f.name).toLowerCase() === name.toLowerCase());

const kb = find(cfg.feld_kuendigen_bis);
if (!kb) {
  throw new Error('Custom Field "' + cfg.feld_kuendigen_bis + '" existiert nicht in Paperless; bitte anlegen (Typ Datum) oder Konfiguration anpassen. Ohne dieses Feld kann nichts abgefragt werden.');
}
const ve = find(cfg.feld_vertragsende);
const fr = find(cfg.feld_frist);

// Stichtag: heute + Vorlauf. lte deckt auch überfällige Termine ab.
const limitDate = new Date(Date.now() + cfg.vorlauf_tage * 86400000).toISOString().slice(0, 10);
const customFieldQuery = JSON.stringify([cfg.feld_kuendigen_bis, 'lte', limitDate]);

return [{ json: Object.assign({}, cfg, {
  kuendigen_bis_id: kb.id,
  vertragsende_id: ve ? ve.id : null,
  frist_id: fr ? fr.id : null,
  limitDate,
  customFieldQuery
}) }];

// HTML-Mail mit allen fälligen Verträgen aufbauen, sortiert nach
// Kündigungstermin (dringendste zuerst), Überfälliges rot markiert.
const cfg = $('Felder prüfen').first().json;
const docs = $json.results || [];
const todayIso = new Date().toISOString().slice(0, 10);
const today = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });

const val = (doc, fieldId) => {
  if (fieldId === null) return null;
  const cf = (doc.custom_fields || []).find(f => f.field === fieldId);
  return cf && cf.value ? cf.value : null;
};
const fmt = (iso) => iso ? new Date(iso).toLocaleDateString('de-DE') : '-';

const list = docs.map(doc => ({
  doc,
  kuendigenBis: val(doc, cfg.kuendigen_bis_id),
  vertragsende: val(doc, cfg.vertragsende_id),
  frist: val(doc, cfg.frist_id),
})).sort((a, b) => String(a.kuendigenBis || '').localeCompare(String(b.kuendigenBis || '')));

const rows = list.map(e => {
  const docUrl = cfg.paperless_url_oeffentlich + '/documents/' + e.doc.id + '/detail';
  const ueberfaellig = e.kuendigenBis && e.kuendigenBis < todayIso;
  return '<tr>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;"><a href="' + docUrl + '" style="color:#1a73e8;">' + (e.doc.title || '(kein Titel)') + '</a></td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;">' + fmt(e.vertragsende) + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;">' + (e.frist || '-') + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;color:#c0392b;font-weight:bold;">' + fmt(e.kuendigenBis) + (ueberfaellig ? ' &#9888;&#65039; &#252;berf&#228;llig' : '') + '</td>'
    + '</tr>';
}).join('\n');

const anzahl = docs.length + (docs.length === 1 ? ' Vertrag' : ' Vertr\u00e4ge');

const html = '<div style="font-family:Arial,sans-serif;max-width:750px;">'
  + '<h2 style="color:#2c3e50;border-bottom:2px solid #2c3e50;padding-bottom:8px;">K&#252;ndigungsfristen &#8211; jetzt handeln</h2>'
  + '<p>F&#252;r <strong>' + anzahl + '</strong> l&#228;uft die K&#252;ndigungsfrist innerhalb der n&#228;chsten ' + cfg.vorlauf_tage + ' Tage ab (oder ist bereits &#252;berschritten):</p>'
  + '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;width:100%;margin:16px 0;">'
  + '<thead><tr style="background:#2c3e50;color:#fff;">'
  + '<th style="padding:10px 12px;text-align:left;">Vertrag</th>'
  + '<th style="padding:10px 12px;text-align:left;">Vertragsende</th>'
  + '<th style="padding:10px 12px;text-align:left;">K&#252;ndigungsfrist</th>'
  + '<th style="padding:10px 12px;text-align:left;">K&#252;ndigen bis</th>'
  + '</tr></thead>'
  + '<tbody>' + rows + '</tbody></table>'
  + '<p style="font-size:13px;color:#555;">Nach K&#252;ndigung oder Verl&#228;ngerung bitte das Feld &#8222;K&#252;ndigen bis&#8220; im Dokument aktualisieren oder leeren &#8212; sonst erscheint der Vertrag n&#228;chste Woche wieder.</p>'
  + '<p><a href=' + cfg.paperless_url_oeffentlich + ' style="background:#2c3e50;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;display:inline-block;">&#8594; Paperless-NGX &#246;ffnen</a></p>'
  + '<p style="color:#95a5a6;font-size:12px;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">Automatisch generiert am ' + today + ' &#183; <a href="https://github.com/paper-werk">Paper-Werk</a></p>'
  + '</div>';

return [{ json: {
  html,
  toEmail: cfg.empfaenger_email,
  fromEmail: cfg.absender,
  subject: 'K\u00fcndigungsfristen: ' + anzahl + ' zu pr\u00fcfen'
} }];
